{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.jan_planning_overall as with targets as ( select date, replace(sales_total,\',\',\'\')::int as target_sales, 1250 as target_asp, 0.15 as discount_pct, ((replace(sales_total,\',\',\'\')::int*0.13)/(0.87))::int as target_discount_amount, (replace(sales_total,\',\',\'\')::int/1265)::int as target_quantity, ((replace(sales_total,\',\',\'\')::int/5.5)*1)::int as target_total_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.85)*1)::int as target_fb_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.09)*1)::int as target_google_spend, (((replace(sales_total,\',\',\'\')::int/5.5)*0.06)*1)::int as target_retention_affilate_spend from SNITCH_DB.MAPLEMONK.MARCH26_SALES_TARGETS where date is not null ), sales_discount as ( select order_timestamp::date as date, sum(discount)/sum(discount+gross_sales) as discount_pct, sum(discount)::int as discount, sum(gross_sales)::int as sales from snitch_db.maplemonk.fact_items_snitch where order_status = \'Shopify_Processed\' and date_trunc(\'month\',order_timestamp::date) = \'2026-03-01\' and case when lower(ifnull(discount_code,\'others\')) like \'%eco%\' or lower(ifnull(discount_code,\'others\')) like \'%influ%\' or lower(ifnull(discount_code,\'others\')) like \'%rms%\' or tags = \'FLITS_LOGICERP\' or lower(ifnull(discount_code,\'others\')) like \'%creator%\' then 1 else 0 end = 0 group by 1 ), main_spends as ( select date, sum(case when channel = \'Facebook\' then spend end)::int-ifnull(((sum(case when channel = \'Facebook\' and (lower(ad_name) like \'brand%\' or lower(adset_name) like \'brand%\') then spend end)::int)),0)-ifnull(sum(case when channel = \'Facebook\' and (lower(ad_name) like \'offline%\' or lower(adset_name) like \'offline%\') then spend end)::int,0)-ifnull(sum(case when channel = \'Facebook\' and (lower(ad_name) like \'plus%\' or lower(adset_name) like \'plus%\') then spend end)::int,0)- ifnull(sum(case when channel = \'Facebook\' and lower(adset_name) like \'%web&instore%\' then spend end),0)*0.7 as facebook, sum(case when channel = \'Google\' then spend end)::int-ifnull(((sum(case when channel = \'Google\' and (lower(ad_name) like \'%brand%\' or lower(adset_name) like \'%brand%\' or lower(campaign_name) like \'%brand%\') then spend end)::int)),0)-ifnull(sum(case when channel = \'Google\' and (lower(ad_name) like \'%offline%\' or lower(adset_name) like \'%offline%\' or lower(campaign_name) like \'%offline%\') then spend end)::int,0)-ifnull(sum(case when channel = \'Google\' and (lower(ad_name) like \'plus%\' or lower(adset_name) like \'plus%\' or lower(campaign_name) like \'plus%\') then spend end)::int,0) as google, sum(case when channel = \'Affiliates\' then spend end)::int as affilates, sum(spend)::int as spend from snitch_db.maplemonk.marketing_consolidated_snitch where date_trunc(\'month\',date) = \'2026-03-01\' group by 1 ), retention as ( SELECT run_date as date, SUM(SPENDS)::int AS retention FROM snitch_db.maplemonk.campaign_reports_summary WHERE CHANNEL IN (\'Sms\', \'WhatsApp\') and date_trunc(\'month\',run_date) = \'2026-03-01\' group by 1 ), north_south_pre as ( select order_date, CASE WHEN warehouse_name like \'%NORTH%\' then \'NORTH\' when warehouse_name like \'%SAPL%\' then \'SOUTH\' else \'OMNI/QCOM\' end as location, count(saleorderitemcode) as units, sum(suborder_quantity) as quant from snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where marketplace_mapped = \'SHOPIFY\' and warehouse_name like \'%SAPL%\' group by 1,2 ), north_south as ( select order_date as date, sum(case when location = \'NORTH\' then units end) as north, sum(case when location = \'SOUTH\' then units end) as south, sum(case when location = \'OMNI/QCOM\' then units end) as omni from north_south_pre group by 1 ), actuals as ( select a.date, a.sales as actual_sales, a.discount_pct as actual_discount_pct, a.discount as actual_discount, facebook as actual_fb_spend, google as actual_google_spend, ifnull(affilates,0)+ifnull(retention,0) as actual_retention_spend, (facebook+google+ifnull(affilates,0)+ifnull(retention,0)) as actual_total_spend, north as actual_north_quantity, south as actual_south_quantity from sales_discount a left join main_spends b on a.date = b.date left join retention c on a.date = c.date left join north_south d on a.date = d.date order by a.date asc ) select a.*, b.actual_sales, b.actual_discount_pct, b.actual_discount, b.actual_fb_spend, b.actual_google_spend, b.actual_retention_spend, b.actual_total_spend, b.actual_north_quantity, b.actual_south_quantity, current_date as today_date from targets a left join actuals b on a.date = b.date ; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.category_wise_trackerjan26 as with base_pre as ( select sku_group, case when lower(ifnull(discount_code,\'others\')) like \'%eco%\' or lower(ifnull(discount_code,\'others\')) like \'%influ%\' or lower(ifnull(discount_code,\'others\')) like \'%rms%\' or tags = \'FLITS_LOGICERP\' or lower(ifnull(discount_code,\'others\')) like \'%creator%\' then 1 else 0 end as removing_flag, order_timestamp::date as date, sum(gross_sales) as gross_sales, sum(quantity) as quantity from snitch_db.maplemonk.fact_items_snitch where order_status = \'Shopify_Processed\' and date_trunc(\'month\',order_timestamp::date) = \'2026-03-01\' group by 1,2,3 ), cat as ( select sku_group, category, style from snitch_db.maplemonk.base_product qualify row_number() over (partition by sku_group order by category asc)= 1 ), base as ( select a.sku_group, a.date, b.style, case when left(a.sku_group,2) = \'BP\' then \'Bags\' when left(a.sku_group,2) = \'SN\' then \'Sunglasses\' when left(a.sku_group,4) = \'4MBL\' then \'Belts\' when left(a.sku_group,4) = \'4MCP\' then \'Caps\' else b.category end as category, sum(gross_sales)::int as gross_sales, sum(quantity)::int as gross_quantity from base_pre a left join cat b on a.sku_group = b.sku_group where removing_flag = 0 group by 1,2,3,4 ), category_actual_sales AS ( SELECT case when left(sku_group,4) = \'4MBG\' then \'Plus\' when lower(style) like \'%luxe%\' then \'Luxe\' else \'Snitch\' end as l1_category, case when lower(style) like \'%luxe%\' then \'Luxe\' else category end as category, SUM(CASE WHEN date = \'2026-03-01\' THEN IFNULL(gross_quantity,0) END) AS qty_01, SUM(CASE WHEN date = \'2026-03-01\' THEN IFNULL(gross_sales,0) END) AS sales_01, SUM(CASE WHEN date = \'2026-03-02\' THEN IFNULL(gross_quantity,0) END) AS qty_02, SUM(CASE WHEN date = \'2026-03-02\' THEN IFNULL(gross_sales,0) END) AS sales_02, SUM(CASE WHEN date = \'2026-03-03\' THEN IFNULL(gross_quantity,0) END) AS qty_03, SUM(CASE WHEN date = \'2026-03-03\' THEN IFNULL(gross_sales,0) END) AS sales_03, SUM(CASE WHEN date = \'2026-03-04\' THEN IFNULL(gross_quantity,0) END) AS qty_04, SUM(CASE WHEN date = \'2026-03-04\' THEN IFNULL(gross_sales,0) END) AS sales_04, SUM(CASE WHEN date = \'2026-03-05\' THEN IFNULL(gross_quantity,0) END) AS qty_05, SUM(CASE WHEN date = \'2026-03-05\' THEN IFNULL(gross_sales,0) END) AS sales_05, SUM(CASE WHEN date = \'2026-03-06\' THEN IFNULL(gross_quantity,0) END) AS qty_06, SUM(CASE WHEN date = \'2026-03-06\' THEN IFNULL(gross_sales,0) END) AS sales_06, SUM(CASE WHEN date = \'2026-03-07\' THEN IFNULL(gross_quantity,0) END) AS qty_07, SUM(CASE WHEN date = \'2026-03-07\' THEN IFNULL(gross_sales,0) END) AS sales_07, SUM(CASE WHEN date = \'2026-03-08\' THEN IFNULL(gross_quantity,0) END) AS qty_08, SUM(CASE WHEN date = \'2026-03-08\' THEN IFNULL(gross_sales,0) END) AS sales_08, SUM(CASE WHEN date = \'2026-03-09\' THEN IFNULL(gross_quantity,0) END) AS qty_09, SUM(CASE WHEN date = \'2026-03-09\' THEN IFNULL(gross_sales,0) END) AS sales_09, SUM(CASE WHEN date = \'2026-03-10\' THEN IFNULL(gross_quantity,0) END) AS qty_10, SUM(CASE WHEN date = \'2026-03-10\' THEN IFNULL(gross_sales,0) END) AS sales_10, SUM(CASE WHEN date = \'2026-03-11\' THEN IFNULL(g